'use client';import {useParams} from 'next/navigation';import {useEffect,useState} from 'react';
export default function Report(){const{coupleId}=useParams<{coupleId:string}>();const[d,setD]=useState<any>();const[busy,setBusy]=useState(false);useEffect(()=>{fetch(`/api/couples?id=${coupleId}`).then(x=>x.json()).then(setD)},[coupleId]);async function buy(){setBusy(true);const x=await fetch('/api/payment',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({coupleId})}).then(r=>r.json());if(x.confirmation_url)location.href=x.confirmation_url;else setBusy(false)}async function generate(){setBusy(true);const x=await fetch('/api/report',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({coupleId})}).then(r=>r.json());setD({...d,report:x.report_json});setBusy(false)}if(!d)return null;if(!d.paid)return <main className="shell"><section className="hero"><div className="eyebrow">полный разбор</div><h1 className="h1" style={{fontSize:52}}>Посмотрите картину целиком.</h1><div className="card"><p>✓ сильные стороны пары</p><p>✓ главные расхождения</p><p>✓ насколько хорошо вы понимаете друг друга</p><p>✓ 5 персональных вопросов</p><h2>299 ₽</h2><p className="tiny">Один отчёт для вас двоих</p></div><button className="btn" onClick={buy} disabled={busy}>{busy?'Переходим к оплате…':'Открыть полный разбор'}</button></section></main>;const rep=d.report;if(!rep)return <main className="shell"><section className="hero center"><h1 className="h1" style={{fontSize:48}}>Оплата подтверждена.</h1><p className="lead">Теперь соберём персональный разбор ваших ответов.</p><button className="btn" onClick={generate} disabled={busy}>{busy?'Собираем разбор…':'Сформировать разбор'}</button></section></main>;return <main className="shell"><div className="brand">между нами</div><h1 className="h1" style={{fontSize:48}}>Ваш полный разбор</h1><div className="card"><h2>01 · В двух словах</h2><p>{rep.summary}</p></div><div className="card"><h2>02 · Сильные стороны</h2>{rep.strengths?.map((x:string)=><p key={x}>{x}</p>)}</div><div className="card"><h2>03 · Где вы видите отношения по-разному</h2>{rep.differences?.map((x:string)=><p key={x}>{x}</p>)}</div><div className="card"><h2>04 · Насколько хорошо вы понимаете друг друга</h2><p>{rep.understanding}</p></div><div className="card"><h2>05 · О чём стоит поговорить</h2>{rep.discuss?.map((x:string,i:number)=><p key={x}>{i+1}. {x}</p>)}</div><div className="card"><h2>06 · Маленький эксперимент</h2><p>{rep.experiment}</p></div></main>}
